//! 🧫️ Native coroutine transitions preserve authored scope and every actual allocation through cancellation.
use super::*;
use semio_os_spr as protocol;
use semio_framework_job::close_original_effect_step;
use semio_os_store_replay::native_supersession::{NativeSupersessionFold,NativeSupersessionSource};
use crate::replacement_tests::{close_decoder,clock,quoted_turn,source_stock,stock,turn};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner};
fn schedule(cutoff:Option<usize>){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let document=law["document"].as_str().unwrap();let events:Vec<_>=law["events"].as_array().unwrap().iter().enumerate().map(|(position,event)|{let transition=protocol::HistoryTransition::Supersede(protocol::TransitionSupersede{scope:event["scope"].as_str().map(str::to_owned),inputs:event["inputs"].as_array().unwrap().iter().map(|input|protocol::SupersededInput{target:MutationId(input["target"].as_str().unwrap().into()),replacement:if input["withdrawn"]==true{protocol::InputReplacement::Withdrawn}else{protocol::InputReplacement::Input{schema:input["schema"].as_str().unwrap().into(),payload:input["payload"].as_str().unwrap().as_bytes().to_vec()}}}).collect()});protocol::history_transition_envelope(&transition,&protocol::ArtifactId(document.into()),&protocol::ActorId("original-actor".into()),Vec::new(),protocol::HybridLogicalTimestamp::new(0,position as u64))}).collect();let pointers:Vec<_>=events.iter().map(|event|event.diff.payload.retained_bytes().contiguous_at(0).map(|bytes|bytes.as_ptr())).collect();let mut owner=NativeSupersessionFold::default();let mut table=semio_os_store_replay::EffectiveSupersessions::new();let mut caller=OriginalJobFixtureCaller::admit(OperationId(998),Generation(18),source_stock(),clock,u64::MAX,16*1024*1024);caller.retain_dispatch().unwrap();let mut decoder=OriginalJobDecodeOwner::empty();let mut position=0;let mut complete=false;
 for step in 0..200000{if cutoff==Some(step){break}let source=events.get(position).map(|event|NativeSupersessionSource{event,previous:position.checked_sub(1).and_then(|at|events.get(at)),document,line:None});let no_grant=RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let original_table=table.len();let (result, heap) = turn(&mut caller, &mut decoder, |cx| {
  let mut observed = None;
  cx.with_retained_loan(no_grant, |cx| {
   observed = Some(semio_framework_trace::observe_heap_allocations_on_this_thread(|| owner.advance(source, &mut table, cx)));
   Ok(())
  })?;
  Ok(observed.expect("zero-grant replay probe ran"))
 });assert!(matches!(result,Ok(None)|Ok(Some(false))),"refused original supersession turn={step} event={position} result={result:?}");assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(table.len(),original_table);
 let source=events.get(position).map(|event|NativeSupersessionSource{event,previous:position.checked_sub(1).and_then(|at|events.get(at)),document,line:None});let demand=owner.original_job_demand(4096).unwrap();match quoted_turn(&mut caller,&mut decoder,demand,|cx|owner.advance(source,&mut table,cx)){Some(true)=>position+=1,Some(false)=>{complete=true;break},None=>{}}
 if owner.active(){let mut foreign=OriginalJobFixtureCaller::admit(OperationId(998),Generation(18),source_stock(),clock,u64::MAX,16*1024*1024);let source=events.get(position).map(|event|NativeSupersessionSource{event,previous:position.checked_sub(1).and_then(|at|events.get(at)),document,line:None});let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.bare_turn(stock(),|cx|owner.advance(source,&mut table,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));foreign.retire(stock());}}
 if cutoff.is_none(){assert!(complete,"native supersession coroutine must finish at event={position} quote={:?}",owner.original_job_demand(4096));let actual:serde_json::Map<String,serde_json::Value>=table.iter().map(|(target,value)|(target.0.clone(),serde_json::Value::from(match &value.replacement{protocol::InputReplacement::Withdrawn=>"withdrawn",protocol::InputReplacement::Input{..}=>"input"}))).collect();assert_eq!(serde_json::Value::Object(actual),law["expected"]);}
 owner.begin_close();for _ in 0..200000{let demand=owner.close_demands(4096).unwrap();if quoted_turn(&mut caller,&mut decoder,demand,|cx|owner.close(cx)){break}}assert!(owner.terminal_is_empty());assert_eq!(events.iter().map(|event|event.diff.payload.retained_bytes().contiguous_at(0).map(|bytes|bytes.as_ptr())).collect::<Vec<_>>(),pointers);drop(owner);let mut table=ControlledRetirement::new(table).ok().unwrap();while !table.terminal_is_empty(){turn(&mut caller,&mut decoder,|cx|close_original_effect_step(cx,table.next_demand(cx.retained_grant().maximum_copy_bytes)?,|effect|table.step(effect.grant().maximum_copy_bytes,effect)).map(|_|()));}close_decoder(&mut caller,&mut decoder);caller.retire(stock());
}
#[test]
fn native_supersession_scope_and_cancellation_match_json_oracle_and_original_physical_receipts(){schedule(None);let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for cutoff in law["cancelPrefixes"].as_array().unwrap(){schedule(Some(cutoff.as_u64().unwrap()as usize));}}
